@@ -63,11 +63,12 @@ final class InstantPeriodicTask implements Callable<Void>, Disposable {

     @Override
     public void dispose() {
-        Future<?> current = first.getAndSet(CANCELLED);
-        if (current != null && current != CANCELLED) {
-            current.cancel(runner != Thread.currentThread());
-        }
-        current = rest.getAndSet(CANCELLED);
+        disposeFuture(first);
+        disposeFuture(rest);
+    }
+
+    private void disposeFuture(AtomicReference<Future<?>> ref) {
+        Future<?> current = ref.getAndSet(CANCELLED);
         if (current != null && current != CANCELLED) {
